"""Packet/parser tests against an actual-adapter model and independent G72 data."""
from pathlib import Path
import argparse,hashlib,json,struct,subprocess
p=argparse.ArgumentParser();p.add_argument('--fixture',type=Path,required=True);p.add_argument('--native-evidence',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();a.output.mkdir(parents=True);W=Path(__file__).resolve().parent;exe=a.output/'client-policy-model'
j=json.loads((a.native_evidence/'native-evidence.json').read_text());expected=a.output/'native-G72-fixed50.bin';expected.write_bytes(struct.pack('<50I',*[x['value']for x in j['snapshot_before']['values']]))
names=['test-client-policy.c','g74_client_policy.c'];q=subprocess.run(['clang','-std=c11','-O1','-Wall','-Wextra','-Werror','-fsanitize=address,undefined','-fno-omit-frame-pointer',*[str(W/n)for n in names],'-o',str(exe)],capture_output=True,text=True);assert not q.returncode,(q.stdout,q.stderr)
q=subprocess.run([str(exe),str(a.fixture),str(expected)],capture_output=True,text=True);assert not q.returncode and not q.stderr,(q.stdout,q.stderr);r=json.loads(q.stdout);r.update(source_sha256={n:hashlib.sha256((W/n).read_bytes()).hexdigest()for n in names+['g74_client_policy.h','g74_protocol.h','g74_power.h','g74_observer.h']},fixture_sha256=hashlib.sha256(a.fixture.read_bytes()).hexdigest(),expected50_sha256=hashlib.sha256(expected.read_bytes()).hexdigest(),G72_evidence_sha256=hashlib.sha256((a.native_evidence/'native-evidence.json').read_bytes()).hexdigest(),sanitizers=['AddressSanitizer','UndefinedBehaviorSanitizer']);(a.output/'tests.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps(r))
